-- Le Guess Who? zones, at Diogo's request: "Domplein" is renamed
-- "Binnenstad" and takes in ACU and Moira, which leaves "Lucasbolwerk" as
-- Stadsschouwburg on its own (renamed to match). Moving two rooms shifts
-- both zones' centres, so the walking times change with them.
--
-- This is the first migration to carry the generator's sync form (insert or
-- update every Zone, Stage and ZoneWalk row), so it also restates the
-- earlier Wijk C/Pijlsweerd rename. Ids and slugs never change. Marks and
-- sets are untouched: no Performance row references a zone.

-- BEGIN generated by `npm run import:lgw -- --sql`; do not edit by hand.
ON CONFLICT ("id") DO UPDATE SET "name" = EXCLUDED."name", "order" = EXCLUDED."order", "walkMinutesFromHub" = EXCLUDED."walkMinutesFromHub";

ON CONFLICT ("id") DO UPDATE SET "zoneId" = EXCLUDED."zoneId", "name" = EXCLUDED."name", "address" = EXCLUDED."address", "order" = EXCLUDED."order", "updatedAt" = CURRENT_TIMESTAMP;

ON CONFLICT ("id") DO UPDATE SET "minutes" = EXCLUDED."minutes";
-- END generated
